def graph(d,forced={}):
 g={};ext=[];bad=[]
 for a,s in d.items():
  op=s.split()[0];t=re.findall(r'0x[0-9a-f]+',s.split('<',1)[0]);t=int(t[-1],16) if t else None
  if op=='ret':ns=[]
  elif op=='b':ns=[t]
  elif op.startswith('b.') or op in ['cbz','cbnz','tbz','tbnz']:ns=[a+4,t]
  elif op in ['br','braa','blrab']:ns=[];bad.append([hex(a),s])
  else:ns=[a+4]
  if a in forced:assert forced[a] in ns;ns=[forced[a]]
  ext.extend([hex(a),hex(v)] for v in ns if v not in d);g[a]=[v for v in ns if v in d]
 assert not ext and not bad,(ext,bad)
 return g
def reach(g,entry,ban=set()):
 seen=set();todo=[entry]
 while todo:
  a=todo.pop()
  if a in seen or a in ban:continue
  seen.add(a);todo.extend(g.get(a,[]))
 return seen
